BEGIN;
ALTER TABLE public.roles ADD COLUMN IF NOT EXISTS workspace text;
UPDATE public.roles SET workspace=CASE role_key WHEN 'clinic_admin' THEN 'administration' WHEN 'doctor' THEN 'clinical' WHEN 'nurse' THEN 'clinical' WHEN 'receptionist' THEN 'operation' WHEN 'accounting' THEN 'administration' ELSE NULL END WHERE workspace IS NULL;
ALTER TABLE public.roles DROP CONSTRAINT IF EXISTS roles_workspace_check;ALTER TABLE public.roles ADD CONSTRAINT roles_workspace_check CHECK(workspace IS NULL OR workspace IN('administration','operation','clinical'));
ALTER TABLE public.clinic_users ADD COLUMN IF NOT EXISTS role_id uuid;
UPDATE public.clinic_users cu SET role_id=COALESCE(cu.role_template_id,r.id) FROM public.roles r WHERE cu.role_id IS NULL AND r.role_key=cu.role AND (r.is_system_role=true OR r.tenant_id=cu.tenant_id);
ALTER TABLE public.clinic_users ALTER COLUMN role_id SET NOT NULL;ALTER TABLE public.clinic_users DROP CONSTRAINT IF EXISTS clinic_users_role_id_fkey;ALTER TABLE public.clinic_users ADD CONSTRAINT clinic_users_role_id_fkey FOREIGN KEY(role_id) REFERENCES public.roles(id) ON DELETE RESTRICT;CREATE INDEX IF NOT EXISTS idx_clinic_users_role_id ON public.clinic_users(role_id);ALTER TABLE public.clinic_users DROP CONSTRAINT IF EXISTS clinic_users_role_check;
CREATE TABLE IF NOT EXISTS public.clinic_user_permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.master_tenants(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.clinic_users(id) ON DELETE CASCADE,permission_id uuid NOT NULL REFERENCES public.permissions(id) ON DELETE CASCADE,granted boolean NOT NULL DEFAULT true,created_by uuid REFERENCES public.clinic_users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id,permission_id));CREATE INDEX IF NOT EXISTS idx_clinic_user_permissions_user ON public.clinic_user_permissions(tenant_id,user_id);
CREATE TABLE IF NOT EXISTS public.clinic_user_settings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.master_tenants(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.clinic_users(id) ON DELETE CASCADE,locale text,timezone text,date_format text,time_format text,default_workspace text,sidebar_collapsed boolean NOT NULL DEFAULT false,preferences jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id),CHECK(default_workspace IS NULL OR default_workspace IN('administration','operation','clinical')));
CREATE TABLE IF NOT EXISTS public.permission_bundles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid REFERENCES public.master_tenants(id) ON DELETE CASCADE,bundle_key text NOT NULL,bundle_name text NOT NULL,bundle_name_ar text,description text,is_system_bundle boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());CREATE UNIQUE INDEX IF NOT EXISTS uq_permission_bundles_system_key ON public.permission_bundles(bundle_key) WHERE is_system_bundle=true;CREATE UNIQUE INDEX IF NOT EXISTS uq_permission_bundles_tenant_key ON public.permission_bundles(tenant_id,bundle_key) WHERE is_system_bundle=false;
CREATE TABLE IF NOT EXISTS public.permission_bundle_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bundle_id uuid NOT NULL REFERENCES public.permission_bundles(id) ON DELETE CASCADE,permission_id uuid NOT NULL REFERENCES public.permissions(id) ON DELETE CASCADE,UNIQUE(bundle_id,permission_id));
CREATE TABLE IF NOT EXISTS public.role_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),template_key text NOT NULL,template_name text NOT NULL,template_name_ar text,description text,workspace text,is_system_template boolean NOT NULL DEFAULT true,tenant_id uuid REFERENCES public.master_tenants(id) ON DELETE CASCADE,source_role_id uuid REFERENCES public.roles(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(workspace IS NULL OR workspace IN('administration','operation','clinical')));CREATE UNIQUE INDEX IF NOT EXISTS uq_role_templates_system_key ON public.role_templates(template_key) WHERE is_system_template=true;CREATE UNIQUE INDEX IF NOT EXISTS uq_role_templates_tenant_key ON public.role_templates(tenant_id,template_key) WHERE is_system_template=false;
CREATE TABLE IF NOT EXISTS public.role_template_permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),template_id uuid NOT NULL REFERENCES public.role_templates(id) ON DELETE CASCADE,permission_id uuid NOT NULL REFERENCES public.permissions(id) ON DELETE CASCADE,UNIQUE(template_id,permission_id));
INSERT INTO public.role_templates(template_key,template_name,template_name_ar,description,workspace,is_system_template,source_role_id) SELECT role_key,role_name,role_name_ar,description,workspace,true,id FROM public.roles WHERE is_system_role=true AND role_key<>'super_admin' ON CONFLICT DO NOTHING;
INSERT INTO public.role_template_permissions(template_id,permission_id) SELECT rt.id,rp.permission_id FROM public.role_templates rt JOIN public.roles r ON r.id=rt.source_role_id JOIN public.role_permissions rp ON rp.role_id=r.id ON CONFLICT DO NOTHING;
ALTER TABLE public.clinic_user_permissions ENABLE ROW LEVEL SECURITY;ALTER TABLE public.clinic_user_settings ENABLE ROW LEVEL SECURITY;ALTER TABLE public.permission_bundles ENABLE ROW LEVEL SECURITY;ALTER TABLE public.permission_bundle_items ENABLE ROW LEVEL SECURITY;ALTER TABLE public.role_templates ENABLE ROW LEVEL SECURITY;ALTER TABLE public.role_template_permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY ajm1_cup_select ON public.clinic_user_permissions FOR SELECT TO authenticated USING(tenant_id=get_current_tenant_id());CREATE POLICY ajm1_cup_write ON public.clinic_user_permissions FOR ALL TO authenticated USING(tenant_id=get_current_tenant_id()) WITH CHECK(tenant_id=get_current_tenant_id());CREATE POLICY ajm1_cus_select ON public.clinic_user_settings FOR SELECT TO authenticated USING(tenant_id=get_current_tenant_id());CREATE POLICY ajm1_cus_write ON public.clinic_user_settings FOR ALL TO authenticated USING(tenant_id=get_current_tenant_id()) WITH CHECK(tenant_id=get_current_tenant_id());CREATE POLICY ajm1_pb_select ON public.permission_bundles FOR SELECT TO authenticated USING(is_system_bundle OR tenant_id=get_current_tenant_id());CREATE POLICY ajm1_pb_write ON public.permission_bundles FOR ALL TO authenticated USING(NOT is_system_bundle AND tenant_id=get_current_tenant_id()) WITH CHECK(NOT is_system_bundle AND tenant_id=get_current_tenant_id());CREATE POLICY ajm1_pbi_select ON public.permission_bundle_items FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.permission_bundles b WHERE b.id=bundle_id AND (b.is_system_bundle OR b.tenant_id=get_current_tenant_id())));CREATE POLICY ajm1_pbi_write ON public.permission_bundle_items FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.permission_bundles b WHERE b.id=bundle_id AND NOT b.is_system_bundle AND b.tenant_id=get_current_tenant_id())) WITH CHECK(EXISTS(SELECT 1 FROM public.permission_bundles b WHERE b.id=bundle_id AND NOT b.is_system_bundle AND b.tenant_id=get_current_tenant_id()));CREATE POLICY ajm1_rt_select ON public.role_templates FOR SELECT TO authenticated USING(is_system_template OR tenant_id=get_current_tenant_id());CREATE POLICY ajm1_rt_write ON public.role_templates FOR ALL TO authenticated USING(NOT is_system_template AND tenant_id=get_current_tenant_id()) WITH CHECK(NOT is_system_template AND tenant_id=get_current_tenant_id());CREATE POLICY ajm1_rtp_select ON public.role_template_permissions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.role_templates t WHERE t.id=template_id AND (t.is_system_template OR t.tenant_id=get_current_tenant_id())));CREATE POLICY ajm1_rtp_write ON public.role_template_permissions FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.role_templates t WHERE t.id=template_id AND NOT t.is_system_template AND t.tenant_id=get_current_tenant_id())) WITH CHECK(EXISTS(SELECT 1 FROM public.role_templates t WHERE t.id=template_id AND NOT t.is_system_template AND t.tenant_id=get_current_tenant_id()));
COMMIT;
